using System;
using System.Collections.Generic;
using System.Text;
using System.Web;
using System.IO;
using System.ServiceModel;
using System.Reflection;
using System.Configuration;
using System.ServiceModel.Configuration;
using System.Runtime.InteropServices;

namespace Sunplus.Agent.Configurations
{
    using Nini.Config;

    /// <summary>
    /// This class will be used in singleton pattern. It could be used in 2 modes: a WCF service or a local http context.
    /// </summary>
    [ServiceBehavior(InstanceContextMode = InstanceContextMode.Single, ConcurrencyMode = ConcurrencyMode.Multiple)]
    public class Configuration : IConfiguration, IDisposable
    {
        IniConfigSource _source = null;
        static object ReloadLocker = new object();

        DateTime LastAccessTime = DateTime.MinValue;
        public string FilePath = null;

        const int LIMIT_RELOAD_INTERVAL = 2;

        internal delegate void UpdateEventHandler(object sender, bool error);

        internal event UpdateEventHandler LoadComplete = delegate { };
        internal event UpdateEventHandler SaveComplete = delegate { };

        public string CurrentDirectory
        {
            get
            {
                if (HttpContext.Current == null)
                {
                    string codeBase = Assembly.GetExecutingAssembly().CodeBase;
                    UriBuilder uri = new UriBuilder(codeBase);
                    string path = Uri.UnescapeDataString(uri.Path);
                    return Path.GetDirectoryName(path) + '\\';
                }
                else
                {
                    return HttpContext.Current.Server.MapPath("~/");
                }
            }
        }

        public void LoadConfigFile()
        {
            if (!File.Exists(FilePath))
            {
                return;
            }

            bool error = false;

            IniConfigSource source = _source;
            FileStream stream = null;

            lock (ReloadLocker)
            {
                try
                {
                    stream = File.Open(FilePath, FileMode.Open, FileAccess.Read, FileShare.ReadWrite);
                    source = new IniConfigSource(stream);
                    source.CaseSensitive = false;
                    LastAccessTime = DateTime.Now;
                }
                catch
                {
                    error = true;
                }
                finally
                {
                    if (stream != null)
                    {
                        stream.Close();
                        stream.Dispose();
                    }
                }
            }

            if (source == null)
            {
                throw new Exception("Cannot init configuration with \"" + FilePath + "\"");
            }

            // First time
            if (_source == null)
            {
                _source = source;
            }
            else
            {
                lock (_source) // Lock access when swap memory
                {
                    _source = source;
                }
            }

            OnLoadComplete(error);
        }

        public void SaveConfigFile()
        {
            if (!File.Exists(FilePath))
            {
                return;
            }

            bool error = false;

            FileStream stream = null;
            try
            {
                stream = File.Open(FilePath, FileMode.Open, FileAccess.Read, FileShare.ReadWrite);
                _source.Save(stream);
                LastAccessTime = DateTime.Now;
            }
            catch
            {
                error = true;
            }
            finally
            {
                if (stream != null)
                {
                    stream.Flush();
                    stream.Close();
                    stream.Dispose();
                }
            }

            OnSaveComplete(error);
        }

        protected void OnLoadComplete(bool error)
        {
            LoadComplete(this, error);
        }

        protected void OnSaveComplete(bool error)
        {
            SaveComplete(this, error);
        }

        public Configuration(string fileName)
        {
            string appPath = CurrentDirectory;
            FilePath = appPath + fileName;

            if (!File.Exists(FilePath))
            {
                throw new FileNotFoundException("Cannot find file or directory \"" + FilePath + "\"", FilePath);
            }

            // Add to change watcher
            ChangedWatcher.Add(this, appPath);
        }


        #region IConfiguration Members


        public void Load()
        {
            Reload();
        }

        public void Reload()
        {
            if (DateTime.Now.Subtract(LastAccessTime) > TimeSpan.FromSeconds(LIMIT_RELOAD_INTERVAL))
            {
                LoadConfigFile();
            }
        }

        public string Get(string alias)
        {
            return _source.Configs[0].Get(alias, alias);
        }

        public IList<string> Get(IList<string> alias)
        {
            var ret = new List<string>();

            foreach (string s in alias)
                ret.Add(_source.Configs[0].Get(s, s));

            return ret;
        }

        public string[] GetKeys()
        {
            return _source.Configs[0].GetKeys();
        }

        public string[] GetValues()
        {
            return _source.Configs[0].GetValues();
        }

        public void SetValue(string key, string value)
        {
            _source.Configs[0].Set(key, value);
        }

        public void Contains(string key)
        {
            _source.Configs[0].Contains(key);
        }

        public void Save()
        {
            if (DateTime.Now.Subtract(LastAccessTime) > TimeSpan.FromSeconds(LIMIT_RELOAD_INTERVAL))
            {
                lock (ReloadLocker)
                {
                    if (DateTime.Now.Subtract(LastAccessTime) > TimeSpan.FromSeconds(LIMIT_RELOAD_INTERVAL))
                    {
                        SaveConfigFile();
                    }
                }
            }
        }

        #endregion


        #region IDisposable Members

        void IDisposable.Dispose()
        {

        }

        #endregion
    }
